type WorkerNode = { id:string;name:string;platform:string;version:string;status:string;active_jobs:number;max_concurrency:number;runtime_json:string;health_json:string;capabilities_json:string;last_seen_at:string };
type Rule = { id:string;name:string;kind:string;enabled:number;created_at:string };
