const empty:StudioData={workspace:null,templates:[],projects:[],sources:[],workflows:[],runs:[],events:[],checkpoints:[],evidence:[],evidenceLinks:[],relationships:[],plugins:[],profiles:[],nodes:[],rules:[],auditLogs:[],deliveryLogs:[],skills:[]};
const platforms:Record<string,string>={geo:'GEO 官网观测',bluesky:'Bluesky',reddit:'Reddit',youtube:'YouTube',tiktok:'TikTok',douyin:'抖音',xiaohongshu:'小红书',rss:'RSS / Atom',rest:'REST API',web:'公开网页','opencli:hackernews':'Hacker News','opencli:zhihu':'知乎','opencli:bilibili':'Bilibili','opencli:weibo':'微博','opencli:twitter':'X / Twitter','opencli:linkedin':'LinkedIn','opencli:xueqiu':'雪球','opencli:eastmoney':'东方财富'};
const nodeMeta:Record<NodeType,{label:string;icon:string;copy:string}>={source:{label:'采集来源',icon:'◎',copy:'可并行的项目来源或平台'},normalize:{label:'数据归一化',icon:'≋',copy:'统一字段、语言与时间'},dedupe:{label:'跨任务去重',icon:'◇',copy:'来源 ID 与内容指纹合并'},filter:{label:'条件过滤',icon:'⌁',copy:'按字段或表达式筛选记录'},gate:{label:'质量闸门',icon:'⊢',copy:'不满足阈值时停止或跳过'},cluster:{label:'语义聚类',icon:'⌘',copy:'发现相似主题'},llm:{label:'AI 研究',icon:'✦',copy:'摘要、标签与严重度'},agent:{label:'Agent 节点',icon:'◈',copy:'受限工具与多步研究'},report:{label:'证据报告',icon:'▤',copy:'记录、证据与血缘'},dataset:{label:'数据集写入',icon:'▧',copy:'追加或覆盖结构化数据集'},deliver:{label:'自动交付',icon:'↗',copy:'Webhook、消息与邮件网关'}};
const tabs:Array<{id:Tab;label:string;icon:string}>=[{id:'projects',label:'项目',icon:'▦'},{id:'workflow',label:'工作流画布',icon:'⌘'},{id:'runs',label:'运行与 Trace',icon:'◉'},{id:'evidence',label:'证据关系',icon:'⟠'},{id:'resources',label:'执行资源',icon:'▣'},{id:'plugins',label:'插件中心',icon:'◆'},{id:'delivery',label:'治理与交付',icon:'✓'},{id:'access',label:'团队与权限',icon:'♙'}];

function safeJson<T>(value:string,fallback:T):T{try{return JSON.parse(value) as T;}catch{return fallback;}}
function sourceFromNode(node:WorkflowNode):SourceSpec{const projectSourceId=typeof node.config['projectSourceId']==='string'?node.config['projectSourceId']:undefined;return{platform:String(node.config['platform']??'bluesky'),keyword:String(node.config['keyword']??''),limit:Number(node.config['limit']??100),includeComments:node.config['includeComments']!==false,...(projectSourceId?{projectSourceId}:{})};}
function layoutNodes(nodes:WorkflowNode[]):WorkflowNode[]{const sources=nodes.filter(node=>node.type==='source'),processing=nodes.filter(node=>node.type!=='source');return[...sources.map((node,index)=>({...node,x:Number.isFinite(node.x)&&node.x>0?node.x:45,y:Number.isFinite(node.y)&&node.y>0?node.y:35+index*135,label:node.label||`采集来源 ${index+1}`})),...processing.map((node,index)=>({...node,x:Number.isFinite(node.x)&&node.x>0?node.x:260+index*190,y:Number.isFinite(node.y)&&node.y>0?node.y:105}))];}
function specWith(nodes:WorkflowNode[],edges:WorkflowEdge[]):WorkflowSpec{const positioned=layoutNodes(nodes),sources=positioned.filter(node=>node.type==='source').map(sourceFromNode),source=sources[0]??{platform:'bluesky',keyword:'',limit:100,includeComments:true};return{source,sources,steps:positioned.filter(node=>node.type!=='source').map(node=>node.type),nodes:positioned,edges};}
function parseSpec(workflow:Workflow):WorkflowSpec{const fallback:WorkflowSpec={source:{platform:'bluesky',keyword:'',limit:100,includeComments:true},sources:[],steps:[],nodes:[],edges:[]};const parsed=safeJson(workflow.draft_json,fallback);if(!parsed.nodes?.length){const legacySources=parsed.sources?.length?parsed.sources:[parsed.source];parsed.nodes=legacySources.map((source,index)=>({id:`source-${index+1}`,type:'source',label:`采集来源 ${index+1}`,x:45,y:35+index*135,config:{...source}}));for(const [index,type] of (parsed.steps??[]).entries())parsed.nodes.push({id:`${type}-${index+1}`,type:type as NodeType,label:nodeMeta[type as NodeType]?.label??type,x:0,y:0,config:{}});}const ids=new Set(parsed.nodes.map(node=>node.id)),validEdges=(parsed.edges??[]).filter(edge=>ids.has(edge.source)&&ids.has(edge.target)&&edge.source!==edge.target);return validEdges.length?specWith(parsed.nodes,validEdges):rebuildGraph(parsed.nodes);}
function rebuildGraph(nodes:WorkflowNode[]):WorkflowSpec{
  const sourceNodes=nodes.filter(node=>node.type==='source');
  const processing=nodes.filter(node=>node.type!=='source');
  const positioned=[...sourceNodes.map((node,index)=>({...node,x:45,y:35+index*135,label:node.label||`采集来源 ${index+1}`})),...processing.map((node,index)=>({...node,x:260+index*190,y:105}))];
  const first=processing[0];
  const edges:WorkflowEdge[]=[...(first?sourceNodes.map((node,index)=>({id:`edge-source-${index+1}`,source:node.id,target:first.id})):[]),...processing.slice(1).map((node,index)=>({id:`edge-step-${index+1}`,source:processing[index]!.id,target:node.id}))];
  return specWith(positioned,edges);
}
function reaches(spec:WorkflowSpec,start:string,target:string):boolean{const queue=[start],seen=new Set<string>();while(queue.length){const current=queue.shift()!;if(current===target)return true;if(seen.has(current))continue;seen.add(current);for(const edge of spec.edges)if(edge.source===current)queue.push(edge.target);}return false;}
function date(value:string|null){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—';}
function safeProfileUrl(value:string|null|undefined){if(!value)return'';try{const url=new URL(value),loopback=['localhost','127.0.0.1','[::1]'].includes(url.hostname);if((url.protocol!=='https:'&&!(url.protocol==='http:'&&loopback))||url.username||url.password)return'';url.search='';url.hash='';return url.toString();}catch{return'';}}

function BrowserAutomationPanel({profiles,nodes,canWrite}:{profiles:Profile[];nodes:WorkerNode[];canWrite:boolean}){
  const [sessions,setSessions]=useState<BrowserSession[]>([]),[actions,setActions]=useState<BrowserAction[]>([]),[selected,setSelected]=useState(''),[actionType,setActionType]=useState('tabs.list'),[message,setMessage]=useState(''),[loading,setLoading]=useState(false);
  const load=useCallback(async()=>{try{const response=await fetch('/api/browser',{cache:'no-store'}),body=await response.json() as {sessions?:BrowserSession[];actions?:BrowserAction[];error?:string};if(!response.ok)throw new Error(body.error??'浏览器会话加载失败');setSessions(body.sessions??[]);setActions(body.actions??[]);setSelected(value=>value&&(body.sessions??[]).some(item=>item.id===value)?value:body.sessions?.[0]?.id??'');setMessage('');}catch(error){setMessage(error instanceof Error?error.message:'浏览器会话加载失败');}},[]);
  useEffect(()=>{const initial=window.setTimeout(()=>void load(),0),timer=window.setInterval(()=>void load(),4000);return()=>{window.clearTimeout(initial);window.clearInterval(timer);};},[load]);
  const session=sessions.find(item=>item.id===selected),sessionActions=actions.filter(item=>item.session_id===selected);
  async function createSession(event:FormEvent<HTMLFormElement>){event.preventDefault();setLoading(true);const form=event.currentTarget,values=new FormData(form);try{const response=await fetch('/api/browser',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({profileId:values.get('profileId'),nodeId:values.get('nodeId')||undefined,allowlist:String(values.get('allowlist')??'').split(/[\s,]+/).filter(Boolean),timeoutMs:Number(values.get('timeoutMs')),ttlHours:Number(values.get('ttlHours'))})}),body=await response.json() as {session?:BrowserSession;error?:string};if(!response.ok)throw new Error(body.error??'创建会话失败');form.reset();if(body.session)setSelected(body.session.id);await load();}catch(error){setMessage(error instanceof Error?error.message:'创建会话失败');}finally{setLoading(false);}}
  async function closeSession(){if(!session)return;setLoading(true);try{const response=await fetch(`/api/browser/sessions/${session.id}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({action:'close'})}),body=await response.json() as {error?:string};if(!response.ok)throw new Error(body.error??'关闭失败');await load();}catch(error){setMessage(error instanceof Error?error.message:'关闭失败');}finally{setLoading(false);}}
  async function queueAction(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!session)return;setLoading(true);const form=event.currentTarget,values=new FormData(form),input:Record<string,unknown>={};const targetId=String(values.get('targetId')??'').trim(),url=String(values.get('url')??'').trim(),selector=String(values.get('selector')??'').trim(),text=String(values.get('text')??'');if(targetId)input.targetId=targetId;if(url)input.url=url;if(selector)input.selector=selector;if(text)input.text=text;if(values.get('clear'))input.clear=true;try{const response=await fetch(`/api/browser/sessions/${session.id}/actions`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({type:actionType,input})}),body=await response.json() as {error?:string};if(!response.ok)throw new Error(body.error??'提交动作失败');form.reset();setActionType('tabs.list');await load();}catch(error){setMessage(error instanceof Error?error.message:'提交动作失败');}finally{setLoading(false);}}
  return <section className="browser-automation"><div className="section-title"><div><h3>受控浏览器自动化</h3><p>动作经 Worker + Profile 绑定后使用 CDP 执行；禁止 JS/eval、私网与 allowlist 外导航，所有动作留审计。</p></div><button type="button" onClick={()=>void load()}>刷新</button></div>{message&&<p className="browser-error">{message}</p>}<div className="browser-control-grid"><form className="compact-form browser-session-form" onSubmit={createSession}><h4>创建会话</h4><select name="profileId" required defaultValue=""><option value="" disabled>选择浏览器 Profile</option>{profiles.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><select name="nodeId" defaultValue=""><option value="">按 Profile 自动路由 Worker</option>{nodes.map(item=><option key={item.id} value={item.id}>{item.name} · {item.status}</option>)}</select><textarea name="allowlist" required placeholder="允许域名，逗号或换行分隔，例如 example.com, *.example.org"/><label>动作超时 <input name="timeoutMs" type="number" min="3000" max="60000" defaultValue="30000"/></label><label>会话时长 <input name="ttlHours" type="number" min="1" max="24" defaultValue="2"/></label><button disabled={!canWrite||loading||!profiles.length}>创建并连接</button>{!profiles.length&&<small>请先创建浏览器 Profile，并确保绑定 Worker 已配置 CDP endpoint。</small>}</form><div className="browser-session-list"><h4>会话</h4>{sessions.length===0?<p>暂无会话</p>:sessions.map(item=>{const profile=profiles.find(value=>value.id===item.profile_id),node=nodes.find(value=>value.id===item.node_id);return <button type="button" key={item.id} className={selected===item.id?'selected':''} onClick={()=>setSelected(item.id)}><span><strong>{profile?.name??item.profile_id}</strong><small>{node?.name??item.node_id} · {item.capability}</small></span><b className={item.status}>{item.status}</b></button>})}</div></div>{session&&<div className="browser-action-workbench"><header><div><strong>{session.id}</strong><small>Target {session.target_id??'等待创建'} · 超时 {session.timeout_ms}ms · 到期 {date(session.expires_at)}</small><code>{safeJson<string[]>(session.allowlist_json,[]).join(' · ')}</code></div><button type="button" disabled={!canWrite||loading||['closed','closing'].includes(session.status)} onClick={()=>void closeSession()}>关闭会话</button></header>{session.last_error&&<p className="browser-error">{session.last_error}</p>}<form onSubmit={queueAction}><select value={actionType} onChange={event=>setActionType(event.target.value)}><option value="tabs.list">列出标签页</option><option value="tabs.open">打开标签页</option><option value="tabs.close">关闭标签页</option><option value="navigate">导航</option><option value="snapshot">无障碍快照</option><option value="click">点击元素</option><option value="type">输入文本</option><option value="screenshot">截图</option></select>{['tabs.open','navigate'].includes(actionType)&&<input name="url" type="url" required placeholder="allowlist 内的公开 HTTPS URL"/>}{['tabs.close'].includes(actionType)&&<input name="targetId" required placeholder="标签页 Target ID"/>}{['click','type'].includes(actionType)&&<input name="selector" required placeholder="CSS selector（不支持脚本）"/>}{actionType==='type'&&<><input name="text" type="password" autoComplete="off" required placeholder="输入内容（不会出现在审计与结果中）"/><label><input name="clear" type="checkbox"/> 清空原值</label></>}<button disabled={!canWrite||loading||!['active','starting'].includes(session.status)}>提交动作</button></form><div className="browser-action-list">{sessionActions.length===0?<p>暂无动作</p>:sessionActions.map(item=>{const result=safeJson<Record<string,unknown>>(item.result_json??'',{});return <article key={item.id}><i>{item.type}</i><div><strong>{item.status}</strong><small>{date(item.created_at)} · {item.node_id}</small>{item.error&&<em>{item.error}</em>}{Array.isArray(result['tabs'])&&<code>{(result['tabs'] as Array<{title?:string;url?:string}>).map(tab=>`${tab.title||'untitled'} ${tab.url||''}`).join('\n')}</code>}{Array.isArray(result['snapshot'])&&<details><summary>查看快照节点（最多 500）</summary><pre>{JSON.stringify(result['snapshot'],null,2)}</pre></details>}</div>{item.screenshot_key&&<a href={`/api/browser/actions/${item.id}/screenshot`} target="_blank" rel="noreferrer">查看截图 ↗</a>}</article>})}</div></div>}</section>;
}

export function PlatformClient({user}:{user:{displayName:string;email:string}}){
  const [data,setData]=useState<StudioData>(empty),[tab,setTab]=useState<Tab>('projects'),[error,setError]=useState(''),[busy,setBusy]=useState(false);
  const [selectedProject,setSelectedProject]=useState(''),[selectedWorkflow,setSelectedWorkflow]=useState(''),[spec,setSpec]=useState<WorkflowSpec|null>(null),[dragged,setDragged]=useState('');
  const [selectedNode,setSelectedNode]=useState(''),[webhooks,setWebhooks]=useState<WebhookTrigger[]>([]),[webhookToken,setWebhookToken]=useState(''),[copied,setCopied]=useState('');
  const [apiTokens,setApiTokens]=useState<ApiToken[]>([]),[plainToken,setPlainToken]=useState('');
  const [sourceKind,setSourceKind]=useState('opencli');
  const [accessMembers,setAccessMembers]=useState<AccessMember[]>([]),[accessRole,setAccessRole]=useState('viewer'),[inviteUrl,setInviteUrl]=useState('');
  const refresh=useCallback(async(preferredWorkflow?:string)=>{try{const response=await fetch('/api/studio',{cache:'no-store'});const body=await response.json() as StudioData&{error?:string};if(!response.ok)throw new Error(body.error??'加载失败');setData(body);const project=body.projects.find(item=>item.id===selectedProject)?.id??body.projects[0]?.id??'';setSelectedProject(project);const workflow=body.workflows.find(item=>item.id===(preferredWorkflow||selectedWorkflow))??body.workflows.find(item=>item.project_id===project)??body.workflows[0];setSelectedWorkflow(workflow?.id??'');setSpec(workflow?parseSpec(workflow):null);setError('');}catch(caught){setError(caught instanceof Error?caught.message:'加载失败');}},[selectedProject,selectedWorkflow]);
  useEffect(()=>{const initial=window.setTimeout(()=>void refresh(),0);return()=>window.clearTimeout(initial);},[refresh]);
  const workflow=data.workflows.find(item=>item.id===selectedWorkflow)??null;
  const project=data.projects.find(item=>item.id===selectedProject)??null;
  const projectWorkflows=data.workflows.filter(item=>!selectedProject||item.project_id===selectedProject);
  const projectSources=data.sources.filter(item=>item.project_id===selectedProject);
  const selectedFlowNode=spec?.nodes.find(node=>node.id===selectedNode)??spec?.nodes[0]??null;
  const workerPlatforms=useMemo(()=>[...new Set(data.nodes.flatMap(node=>safeJson<string[]>(node.capabilities_json,[])))].filter(item=>!item.includes('/')&&!['source','normalize','dedupe','filter','gate','cluster','llm','agent','report','dataset','deliver'].includes(item)),[data.nodes]);
  const platformCatalog=useMemo(()=>[...new Set([...Object.keys(platforms),...workerPlatforms])].sort((a,b)=>(platforms[a]??a).localeCompare(platforms[b]??b,'zh-CN')),[workerPlatforms]);
  const stats=useMemo(()=>({projects:data.projects.length,activeRuns:data.runs.filter(run=>['queued','running'].includes(run.status)).length,online:data.nodes.filter(node=>node.status==='online').length,evidence:data.evidence.length}),[data]);
  const currentRole=data.workspace?.role??accessRole,canWrite=currentRole!=='viewer',canManageAccess=currentRole==='owner'||currentRole==='admin';

  function requireWrite(){if(canWrite)return;throw new Error('当前角色为 viewer，只能查看，不能修改工作区。');}
  async function postStudio(payload:Record<string,unknown>){requireWrite();const response=await fetch('/api/studio',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const body=await response.json() as {error?:string};if(!response.ok)throw new Error(body.error??'操作失败');}
  async function loadWebhooks(){try{const response=await fetch('/api/integrations/webhooks',{cache:'no-store'});if(!response.ok)return;const body=await response.json() as {triggers?:WebhookTrigger[]};setWebhooks(body.triggers??[]);}catch{/* 集成接口不可用时不影响工作台其他模块 */}}
  async function loadTokens(){try{const response=await fetch('/api/integrations/tokens',{cache:'no-store'});if(!response.ok)return;const body=await response.json() as {tokens?:ApiToken[]};setApiTokens(body.tokens??[]);}catch{/* Token 接口不可用时不影响工作台其他模块 */}}
  const loadAccess=useCallback(async()=>{try{const response=await fetch('/api/admin/access',{cache:'no-store'});if(!response.ok)return;const body=await response.json() as {members?:AccessMember[];currentRole?:string;role?:string};setAccessMembers(body.members??[]);setAccessRole(body.currentRole??body.role??'viewer');}catch{/* 权限接口不可用时保留工作区返回的角色 */}},[]);
  useEffect(()=>{if(tab!=='plugins')return;const timer=window.setTimeout(()=>{void loadWebhooks();void loadTokens();},0);return()=>window.clearTimeout(timer);},[tab]);
  useEffect(()=>{if(tab!=='access')return;const timer=window.setTimeout(()=>void loadAccess(),0);return()=>window.clearTimeout(timer);},[tab,loadAccess]);
  async function createProject(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);const form=event.currentTarget;const values=new FormData(form);try{await postStudio({action:'create-project',name:values.get('name'),description:values.get('description'),template:values.get('template')});form.reset();await refresh();}catch(caught){setError(caught instanceof Error?caught.message:'创建失败');}finally{setBusy(false);}}
  async function createSource(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);const form=event.currentTarget;const values=new FormData(form),kind=String(values.get('kind')??'opencli');const secretName=String(values.get('secretHeader')??'').trim(),secretEnv=String(values.get('secretEnv')??'').trim(),command=String(values.get('command')??'').trim(),rawArgs=String(values.get('args')??'').trim();let args:string[]=[];if(rawArgs){try{const parsed=JSON.parse(rawArgs) as unknown;if(Array.isArray(parsed))args=parsed.map(String);else throw new Error();}catch{args=rawArgs.split(/\r?\n/).map(item=>item.trim()).filter(Boolean);}}const config=kind==='opencli'?{url:values.get('endpoint'),...(command?{command}:{}),...(args.length?{args}:{})}:{url:values.get('endpoint'),itemsPath:values.get('itemsPath'),keyword:values.get('defaultKeyword'),...(secretName&&secretEnv?{secretHeaders:{[secretName]:secretEnv}}:{})};try{await postStudio({action:'create-source',projectId:selectedProject,name:values.get('name'),kind,config});form.reset();setSourceKind('opencli');await refresh();}catch(caught){setError(caught instanceof Error?caught.message:'创建失败');}finally{setBusy(false);}}
  async function testSource(sourceId:string){setBusy(true);try{await postStudio({action:'test-source',sourceId});await refresh();setTab('runs');}catch(caught){setError(caught instanceof Error?caught.message:'试运行失败');}finally{setBusy(false);}}
  async function createWorkflow(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);const form=event.currentTarget;const values=new FormData(form),binding=String(values.get('sourceBinding')??'platform:bluesky');const sourceId=binding.startsWith('source:')?binding.slice(7):'';const registered=projectSources.find(item=>item.id===sourceId);const config=registered?safeJson<Record<string,unknown>>(registered.config_json,{}):{};const platform=registered?(registered.kind==='rss'||registered.kind==='rest'||registered.kind==='web'?registered.kind:String(config['platform']??'bluesky')):binding.slice(9);const source={platform,keyword:values.get('keyword'),limit:Number(values.get('limit')),includeComments:true,...(sourceId?{projectSourceId:sourceId}:{})};try{const response=await fetch('/api/workflows',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({projectId:selectedProject,name:values.get('name'),description:values.get('description'),spec:{source,steps:['normalize','dedupe','cluster','llm','report']}})});const body=await response.json() as {workflow?:Workflow;error?:string};if(!response.ok)throw new Error(body.error);form.reset();await refresh(body.workflow?.id);setTab('workflow');}catch(caught){setError(caught instanceof Error?caught.message:'创建失败');}finally{setBusy(false);}}
  async function workflowAction(action:'save'|'publish'|'run'){if(!workflow||!spec)return;setBusy(true);try{const payload=action==='save'?{revision:workflow.revision,spec}:{action};const response=await fetch(`/api/workflows/${workflow.id}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const body=await response.json() as {error?:string};if(!response.ok)throw new Error(body.error);await refresh(workflow.id);if(action==='run')setTab('runs');}catch(caught){setError(caught instanceof Error?caught.message:'操作失败');}finally{setBusy(false);}}
  function selectWorkflow(id:string){const next=data.workflows.find(item=>item.id===id);setSelectedWorkflow(id);setSpec(next?parseSpec(next):null);setTab('workflow');}
  function updateNodeConfig(patch:Record<string,unknown>){if(!spec||!selectedFlowNode)return;const nodes=spec.nodes.map(node=>node.id===selectedFlowNode.id?{...node,config:{...node.config,...patch}}:node);setSpec(specWith(nodes,spec.edges));}
  function updateNode(key:string,value:unknown){updateNodeConfig({[key]:value});}
  function addNode(type:NodeType){if(!spec||type!=='source'&&spec.nodes.some(node=>node.type===type))return;const count=spec.nodes.filter(node=>node.type===type).length+1;const defaults:Record<NodeType,Record<string,unknown>>={source:{platform:'bluesky',keyword:'',limit:100,includeComments:true},normalize:{schema:'standard-v1'},dedupe:{strategy:'content-hash'},filter:{field:'content',operator:'contains',value:''},gate:{metric:'itemCount',operator:'gte',threshold:1,onReject:'stop'},cluster:{minClusterSize:3},llm:{model:'default',prompt:''},agent:{skillId:data.skills[0]?.id??'',maxIterations:10,instructions:'',allowlist:[]},report:{format:'evidence'},dataset:{name:'research-results',writeMode:'append'},deliver:{channel:'webhook',endpoint:''}};const next={id:`${type}-${spec.nodes.length+1}-${count}`,type,label:type==='source'?`采集来源 ${count}`:nodeMeta[type].label,x:0,y:0,config:defaults[type]};const edges=[...spec.edges];if(type==='source'){const roots=spec.nodes.filter(node=>node.type!=='source'&&!spec.edges.some(edge=>edge.target===node.id));for(const root of roots)edges.push({id:`edge-${next.id}-${root.id}`,source:next.id,target:root.id});}else{const terminals=spec.nodes.filter(node=>!spec.edges.some(edge=>edge.source===node.id));for(const terminal of terminals)edges.push({id:`edge-${terminal.id}-${next.id}`,source:terminal.id,target:next.id});}setSpec(specWith([...spec.nodes,next],edges));setSelectedNode(next.id);}
  function removeNode(id:string){if(!spec)return;const target=spec.nodes.find(node=>node.id===id);if(target?.type==='source'&&spec.nodes.filter(node=>node.type==='source').length===1)return;const incoming=spec.edges.filter(edge=>edge.target===id),outgoing=spec.edges.filter(edge=>edge.source===id),edges=spec.edges.filter(edge=>edge.source!==id&&edge.target!==id);for(const before of incoming)for(const after of outgoing)if(before.source!==after.target&&!edges.some(edge=>edge.source===before.source&&edge.target===after.target))edges.push({id:`edge-${before.source}-${after.target}`,source:before.source,target:after.target});setSpec(specWith(spec.nodes.filter(node=>node.id!==id),edges));if(selectedNode===id)setSelectedNode('');}
  function dropNode(target:string,event:DragEvent<HTMLDivElement>){event.preventDefault();if(!spec||!dragged||dragged===target)return;const moving=spec.nodes.find(node=>node.id===dragged);if(!moving||moving.type==='source')return;const sources=spec.nodes.filter(node=>node.type==='source'),processing=spec.nodes.filter(node=>node.type!=='source'&&node.id!==dragged),index=processing.findIndex(node=>node.id===target);processing.splice(Math.max(0,index),0,moving);const relaid=[...sources,...processing].map(node=>({...node,x:node.type==='source'?node.x:0,y:node.type==='source'?node.y:0}));setSpec(specWith(relaid,spec.edges));setDragged('');}
  function toggleUpstream(upstreamId:string,enabled:boolean){if(!spec||!selectedFlowNode||selectedFlowNode.type==='source')return;const exists=spec.edges.some(edge=>edge.source===upstreamId&&edge.target===selectedFlowNode.id);let edges=spec.edges;if(enabled&&!exists&&!reaches(spec,selectedFlowNode.id,upstreamId))edges=[...edges,{id:`edge-${upstreamId}-${selectedFlowNode.id}`,source:upstreamId,target:selectedFlowNode.id}];if(!enabled&&exists)edges=edges.filter(edge=>!(edge.source===upstreamId&&edge.target===selectedFlowNode.id));setSpec(specWith(spec.nodes,edges));}
  async function createProfile(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);const form=event.currentTarget;const values=new FormData(form);try{await postStudio({action:'create-browser-profile',name:values.get('name'),profileName:values.get('profileName'),profileKind:values.get('profileKind'),mode:values.get('mode'),nodeId:values.get('nodeId'),sites:String(values.get('sites')??'').split(',').map(item=>item.trim()).filter(Boolean),noVncUrl:values.get('noVncUrl'),cdpUrl:values.get('cdpUrl')});form.reset();await refresh();}catch(caught){setError(caught instanceof Error?caught.message:'创建失败');}finally{setBusy(false);}}
  async function createRule(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);const form=event.currentTarget;const values=new FormData(form);try{const response=await fetch('/api/governance',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:values.get('name'),kind:values.get('kind'),endpoint:values.get('endpoint')})});const body=await response.json() as {error?:string};if(!response.ok)throw new Error(body.error);form.reset();await refresh();}catch(caught){setError(caught instanceof Error?caught.message:'创建失败');}finally{setBusy(false);}}
  async function toggleRule(id:string){await fetch(`/api/governance/delivery/${id}`,{method:'PATCH'});await refresh();}
  async function importDify(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);const form=event.currentTarget,values=new FormData(form),file=values.get('file'),projectSourceId=String(values.get('projectSourceId')??'');try{if(!(file instanceof File)||!file.size)throw new Error('请选择 Dify YAML / YML 文件');if(!projectSourceId)throw new Error('请先登记并选择一个项目数据源');const payload=new FormData();payload.set('file',file);payload.set('projectId',String(values.get('projectId')??selectedProject));payload.set('projectSourceId',projectSourceId);const response=await fetch('/api/integrations/dify/import',{method:'POST',body:payload});const body=await response.json() as {error?:string;workflow?:Workflow};if(!response.ok)throw new Error(body.error??'导入失败');form.reset();await refresh(body.workflow?.id);setTab('workflow');}catch(caught){setError(caught instanceof Error?caught.message:'导入失败');}finally{setBusy(false);}}
  async function createWebhook(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);const form=event.currentTarget,values=new FormData(form);try{const response=await fetch('/api/integrations/webhooks',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({projectId:values.get('projectId'),name:values.get('name'),workflowId:values.get('workflowId'),enabled:true})});const body=await response.json() as {error?:string;trigger?:WebhookTrigger;token?:string;webhookUrl?:string};if(!response.ok)throw new Error(body.error??'创建失败');setWebhookToken(body.webhookUrl??(body.token?`${location.origin}/api/integrations/webhooks/${body.token}`:''));form.reset();await loadWebhooks();}catch(caught){setError(caught instanceof Error?caught.message:'创建失败');}finally{setBusy(false);}}
  async function toggleWebhook(trigger:WebhookTrigger){setBusy(true);try{const response=await fetch('/api/integrations/webhooks',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({id:trigger.id,enabled:!Boolean(trigger.enabled)})});const body=await response.json() as {error?:string};if(!response.ok)throw new Error(body.error??'更新失败');await loadWebhooks();}catch(caught){setError(caught instanceof Error?caught.message:'更新失败');}finally{setBusy(false);}}
  async function createToken(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);const form=event.currentTarget,values=new FormData(form),days=Number(values.get('expiresInDays'));try{const response=await fetch('/api/integrations/tokens',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:values.get('name'),role:values.get('role'),...(days>0?{expiresInDays:days}:{})})});const body=await response.json() as {error?:string;token?:string};if(!response.ok)throw new Error(body.error??'创建失败');setPlainToken(body.token??'');form.reset();await loadTokens();}catch(caught){setError(caught instanceof Error?caught.message:'创建失败');}finally{setBusy(false);}}
  async function revokeToken(id:string){setBusy(true);try{const response=await fetch('/api/integrations/tokens',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({id,action:'revoke'})});const body=await response.json() as {error?:string};if(!response.ok)throw new Error(body.error??'撤销失败');await loadTokens();}catch(caught){setError(caught instanceof Error?caught.message:'撤销失败');}finally{setBusy(false);}}
  async function inviteMember(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!canManageAccess){setError('只有 owner 可以邀请和管理成员。');return;}setBusy(true);const form=event.currentTarget,values=new FormData(form);try{const response=await fetch('/api/admin/access',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email:values.get('email'),role:values.get('role')})});const body=await response.json() as {error?:string;token?:string;inviteUrl?:string};if(!response.ok)throw new Error(body.error??'邀请失败');const path=body.inviteUrl??(body.token?`/invite?token=${encodeURIComponent(body.token)}`:'');setInviteUrl(path?new URL(path,location.origin).toString():'');form.reset();await loadAccess();}catch(caught){setError(caught instanceof Error?caught.message:'邀请失败');}finally{setBusy(false);}}
  async function updateMember(id:string,role:string,action?:'remove'){if(!canManageAccess){setError('只有 owner 可以管理成员。');return;}setBusy(true);try{const response=await fetch('/api/admin/access',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(action?{id,action}:{id,role})});const body=await response.json() as {error?:string};if(!response.ok)throw new Error(body.error??'更新失败');await loadAccess();}catch(caught){setError(caught instanceof Error?caught.message:'更新失败');}finally{setBusy(false);}}
  async function copyText(key:string,value:string){try{await navigator.clipboard.writeText(value);setCopied(key);window.setTimeout(()=>setCopied(''),1600);}catch{setError('浏览器未授权剪贴板，请手动复制。');}}

  return <main className={`workbench-shell ${canWrite?'':'read-only'}`} onSubmitCapture={event=>{if(!canWrite){event.preventDefault();setError('当前角色为 viewer，只能查看，不能修改工作区。');}}}>
    <aside className="workbench-nav"><a href="/" className="studio-brand"><span>采</span><b>ThreadBeacon Studio</b></a><div className="workspace-card"><small>WORKSPACE</small><strong>{data.workspace?.name??'个人工作区'}</strong><span>{currentRole} · 私有</span></div><nav>{tabs.map(item=><button key={item.id} className={tab===item.id?'active':''} onClick={()=>setTab(item.id)}><i>{item.icon}</i>{item.label}</button>)}<a href="/docs"><i>?</i>API 文档</a></nav>{!canWrite&&<div className="viewer-note">只读模式 · 写操作已禁用</div>}<div className="studio-account"><span>{user.displayName.slice(0,1)}</span><div><strong>{user.displayName}</strong><small>{user.email}</small></div></div></aside>
    <section className="workbench-main"><header className="workbench-top"><div><p className="eyebrow">Research Intelligence Platform</p><h1>{tabs.find(item=>item.id===tab)?.label}</h1></div><div className="studio-metrics"><span><b>{stats.projects}</b> 项目</span><span><b>{stats.activeRuns}</b> 运行中</span><span><b>{stats.online}</b> 节点在线</span><span><b>{stats.evidence}</b> 证据</span></div><button className="refresh-button" onClick={()=>void refresh()} aria-label="刷新">↻</button></header>{error&&<div className="error-banner studio-error">{error}<button onClick={()=>setError('')}>×</button></div>}

    {tab==='projects'&&<div className="product-page">
      <section className="project-hero"><div><p className="eyebrow">PROJECT COMMAND CENTER</p><h2>把一次采集，变成可持续的研究项目</h2><p>数据源、工作流、运行、证据和交付全部收敛到项目上下文。</p></div><form onSubmit={createProject}><input name="name" required placeholder="新项目名称"/><input name="description" placeholder="研究目标"/><select name="template">{data.templates.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select><button disabled={busy}>创建项目</button></form></section>
      <div className="project-layout"><section><div className="section-title"><div><h3>研究项目</h3><p>选择项目后配置来源和工作流</p></div><span>{data.projects.length}</span></div><div className="project-grid">{data.projects.map(item=><button key={item.id} className={selectedProject===item.id?'selected':''} onClick={()=>setSelectedProject(item.id)}><span className="project-symbol">{item.name.slice(0,1)}</span><div><strong>{item.name}</strong><small>{item.description||'未填写研究说明'}</small><em>{data.sources.filter(source=>source.project_id===item.id).length} 来源 · {data.workflows.filter(flow=>flow.project_id===item.id).length} 工作流</em></div></button>)}{!data.projects.length&&<div className="studio-empty">创建第一个研究项目开始。</div>}</div></section>
      <aside className="project-inspector"><div className="section-title"><div><h3>{project?.name??'项目配置'}</h3><p>来源连接与工作流入口</p></div></div>{project&&<>
        <form className="compact-form" onSubmit={createSource}><input name="name" required placeholder="数据源名称"/><select name="kind" value={sourceKind} onChange={event=>setSourceKind(event.target.value)}><option value="opencli">OpenCLI 平台</option><option value="native">原生 API</option><option value="rss">RSS / Atom</option><option value="rest">REST API</option><option value="web">公开网页</option></select><input name="endpoint" required placeholder={sourceKind==='opencli'?'站点名，如 hackernews / zhihu':'https:// 数据源地址'}/>{sourceKind==='opencli'?<><input name="command" placeholder="只读命令（可选，未填则自动发现）"/><textarea name="args" rows={3} placeholder={'命令参数：JSON 数组或每行一项\n--limit\n20'}/><small>OpenCLI 任意站点均可登记；特殊站点可显式指定只读命令与参数。</small></>:<><input name="defaultKeyword" placeholder="默认关键词（可选）"/><input name="itemsPath" placeholder="REST 数组路径，如 data.items（可选）"/><div className="source-secret-row"><input name="secretHeader" placeholder="密钥头，如 x-api-key"/><input name="secretEnv" placeholder="Worker 环境变量名"/></div><small>密钥只引用 Worker 环境变量，值不会写入数据库。</small></>}<button disabled={busy}>登记来源</button></form>
        <div className="source-stack">{projectSources.map(source=><article key={source.id}><i>{source.kind==='opencli'?'⌘':'◎'}</i><div><strong>{source.name}</strong><small>{source.kind} · {source.status}{source.last_success_at?` · 最近成功 ${date(source.last_success_at)}`:''}{source.consecutive_failures?` · 连续失败 ${source.consecutive_failures}`:''}</small>{source.cursor_json&&<code title={source.cursor_json}>增量游标已保存</code>}{source.last_error&&<em title={source.last_error}>{source.last_error}</em>}</div><button type="button" disabled={busy||source.status==='testing'} onClick={()=>void testSource(source.id)}>{source.status==='testing'?'测试中':'试运行'}</button></article>)}</div>
        <form className="compact-form workflow-create" onSubmit={createWorkflow}><h4>创建可运行工作流</h4><input name="name" required placeholder="工作流名称"/><input name="description" placeholder="用途说明"/><select name="sourceBinding" defaultValue={projectSources[0]?`source:${projectSources[0].id}`:'platform:opencli:hackernews'}>{projectSources.length>0&&<optgroup label="项目数据源">{projectSources.map(source=><option value={`source:${source.id}`} key={source.id}>{source.name} · {source.kind}</option>)}</optgroup>}<optgroup label="直接选择平台">{Object.entries(platforms).filter(([id])=>!['rss','rest','web'].includes(id)).map(([id,name])=><option value={`platform:${id}`} key={id}>{name}</option>)}</optgroup></select><input name="keyword" required placeholder="采集关键词"/><input name="limit" type="number" min="1" max="1000" defaultValue="100"/><button disabled={busy}>创建并打开画布</button></form>
      </>}</aside></div>
    </div>}

    {tab==='workflow'&&<div className="canvas-page">
      <aside className="flow-library"><div className="section-title"><div><h3>工作流</h3><p>多来源 DAG · 草稿与发布版本</p></div></div><div className="workflow-picker">{projectWorkflows.map(item=><button className={item.id===selectedWorkflow?'active':''} key={item.id} onClick={()=>selectWorkflow(item.id)}><strong>{item.name}</strong><small>r{item.revision} · v{item.published_version}</small></button>)}</div><div className="node-library"><h4>节点库</h4>{(Object.keys(nodeMeta) as NodeType[]).map(type=>{const exists=spec?.nodes.some(node=>node.type===type);return <button key={type} disabled={!spec||Boolean(type!=='source'&&exists)} onClick={()=>addNode(type)}><i>{nodeMeta[type].icon}</i><span><strong>{nodeMeta[type].label}</strong><small>{nodeMeta[type].copy}</small></span><b>{type==='source'||!exists?'＋':'✓'}</b></button>})}</div></aside>
      <section className="flow-workspace">{workflow&&spec?<><header className="flow-toolbar"><div><p className="eyebrow">VISUAL WORKFLOW</p><h2>{workflow.name}</h2><span>{spec.nodes.filter(node=>node.type==='source').length} 个来源并行汇聚 · 草稿 r{workflow.revision} · 已发布 v{workflow.published_version}</span></div><div><button onClick={()=>void workflowAction('save')} disabled={busy}>保存草稿</button><button onClick={()=>void workflowAction('publish')} disabled={busy}>验证并发布</button><button className="run-button" onClick={()=>void workflowAction('run')} disabled={busy||!workflow.published_version}>▶ 运行</button></div></header>
        <div className="flow-canvas" style={{minWidth:Math.max(960,(spec.nodes.filter(node=>node.type!=='source').length+1)*190+350),height:Math.max(390,spec.nodes.filter(node=>node.type==='source').length*135+80)}}><svg className="flow-edges" aria-hidden="true"><defs><marker id="flow-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0,0 L7,3.5 L0,7 Z"/></marker></defs>{spec.edges.map(edge=>{const from=spec.nodes.find(node=>node.id===edge.source),to=spec.nodes.find(node=>node.id===edge.target);if(!from||!to)return null;const x1=from.x+145,y1=from.y+56,x2=to.x,y2=to.y+56,curve=Math.max(35,(x2-x1)/2);return <path key={edge.id} d={`M ${x1} ${y1} C ${x1+curve} ${y1}, ${x2-curve} ${y2}, ${x2} ${y2}`} markerEnd="url(#flow-arrow)"/>})}</svg>{spec.nodes.map((node,index)=><div key={node.id} role="button" tabIndex={0} aria-label={`编辑${node.label}`} className={`canvas-node node-${node.type} ${selectedFlowNode?.id===node.id?'selected':''}`} draggable={node.type!=='source'} onClick={()=>setSelectedNode(node.id)} onKeyDown={event=>{if(event.key==='Enter'||event.key===' ')setSelectedNode(node.id)}} onDragStart={()=>setDragged(node.id)} onDragOver={event=>event.preventDefault()} onDrop={event=>dropNode(node.id,event)} style={{left:node.x,top:node.y}}><header><i>{nodeMeta[node.type].icon}</i><small>{String(index+1).padStart(2,'0')}</small></header><strong>{node.label}</strong><p>{nodeMeta[node.type].copy}</p>{(node.type!=='source'||spec.nodes.filter(item=>item.type==='source').length>1)&&<button onClick={event=>{event.stopPropagation();removeNode(node.id)}} aria-label={`删除${node.label}`}>×</button>}</div>)}</div>
        {selectedFlowNode&&<aside className="node-inspector node-inspector-rich"><div><p className="eyebrow">NODE INSPECTOR</p><h3>{selectedFlowNode.label}</h3><span className="node-ready">● 已接入执行器</span></div>
          {selectedFlowNode.type==='source'&&<><label>项目来源<select value={String(selectedFlowNode.config['projectSourceId']??'')} onChange={event=>{const source=projectSources.find(item=>item.id===event.target.value),config=source?safeJson<Record<string,unknown>>(source.config_json,{}):{};updateNodeConfig({projectSourceId:event.target.value,platform:source?(['rss','rest','web'].includes(source.kind)?source.kind:String(config['platform']??selectedFlowNode.config['platform']??'bluesky')):selectedFlowNode.config['platform']??'bluesky'})}}><option value="">直接选择平台</option>{projectSources.map(source=><option key={source.id} value={source.id}>{source.name} · {source.kind}</option>)}</select></label><label>平台<input list="studio-platforms" value={String(selectedFlowNode.config['platform']??'bluesky')} onChange={event=>updateNode('platform',event.target.value)} /><datalist id="studio-platforms">{platformCatalog.map(id=><option value={id} key={id}>{platforms[id]??(id.startsWith('opencli:')?id.slice(8):id)}</option>)}</datalist></label><label>关键词<input value={String(selectedFlowNode.config['keyword']??'')} onChange={event=>updateNode('keyword',event.target.value)}/></label><label>采集上限<input type="number" min="1" max="1000" value={Number(selectedFlowNode.config['limit']??100)} onChange={event=>updateNode('limit',Number(event.target.value))}/></label><label className="check-row"><input type="checkbox" checked={selectedFlowNode.config['includeComments']!==false} onChange={event=>updateNode('includeComments',event.target.checked)}/>采集评论/回复</label></>}
          {selectedFlowNode.type==='filter'&&<><label>字段<input value={String(selectedFlowNode.config['field']??'content')} onChange={event=>updateNode('field',event.target.value)}/></label><label>操作符<select value={String(selectedFlowNode.config['operator']??'contains')} onChange={event=>updateNode('operator',event.target.value)}><option value="contains">包含</option><option value="equals">等于</option><option value="regex">正则匹配</option><option value="gte">大于等于</option><option value="lte">小于等于</option></select></label><label>比较值<input value={String(selectedFlowNode.config['value']??'')} onChange={event=>updateNode('value',event.target.value)}/></label></>}
          {selectedFlowNode.type==='gate'&&<><label>指标<select value={String(selectedFlowNode.config['metric']??'itemCount')} onChange={event=>updateNode('metric',event.target.value)}><option value="itemCount">记录数量</option><option value="qualityScore">质量分</option><option value="sourceCount">成功来源数</option></select></label><label>阈值<input type="number" value={Number(selectedFlowNode.config['threshold']??1)} onChange={event=>updateNode('threshold',Number(event.target.value))}/></label><label>不通过时<select value={String(selectedFlowNode.config['onReject']??'stop')} onChange={event=>updateNode('onReject',event.target.value)}><option value="stop">停止运行</option><option value="skip">跳过后续</option><option value="continue">记录告警并继续</option></select></label></>}
          {selectedFlowNode.type==='agent'&&<><label>绑定 Skill<select required value={String(selectedFlowNode.config['skillId']??'')} onChange={event=>updateNode('skillId',event.target.value)}><option value="" disabled>选择已发布 Skill</option>{data.skills.map(skill=><option key={skill.id} value={skill.id}>{skill.name} · v{skill.current_version}</option>)}</select></label><label>最大迭代<input type="number" min="1" max="50" value={Number(selectedFlowNode.config['maxIterations']??10)} onChange={event=>updateNode('maxIterations',Number(event.target.value))}/></label><label className="inspector-wide">导航 Allowlist<input value={Array.isArray(selectedFlowNode.config['allowlist'])?(selectedFlowNode.config['allowlist'] as string[]).join(', '):''} onChange={event=>updateNode('allowlist',event.target.value.split(/[\s,]+/).filter(Boolean))} placeholder="默认使用 Skill domain，可填写 example.com, *.example.org"/></label><label className="inspector-wide">研究指令<textarea rows={3} value={String(selectedFlowNode.config['instructions']??'')} onChange={event=>updateNode('instructions',event.target.value)} placeholder="描述目标、边界与输出要求"/></label>{!data.skills.length&&<p className="permission-hint">请先到 Skill 治理页创建并发布 Skill。</p>}</>}
          {selectedFlowNode.type==='dataset'&&<><label>数据集名称<input value={String(selectedFlowNode.config['name']??'research-results')} onChange={event=>updateNode('name',event.target.value)}/></label><label>写入方式<select value={String(selectedFlowNode.config['writeMode']??'append')} onChange={event=>updateNode('writeMode',event.target.value)}><option value="append">追加</option><option value="upsert">按来源标识更新</option><option value="replace">覆盖</option></select></label></>}
          {selectedFlowNode.type==='deliver'&&<><label>交付渠道<select value={String(selectedFlowNode.config['channel']??'webhook')} onChange={event=>updateNode('channel',event.target.value)}><option value="webhook">Webhook</option><option value="feishu">飞书</option><option value="dingtalk">钉钉</option><option value="wecom">企业微信</option><option value="email">Email HTTPS Gateway</option></select></label><label className="inspector-wide">HTTPS Endpoint<input type="url" value={String(selectedFlowNode.config['endpoint']??'')} onChange={event=>updateNode('endpoint',event.target.value)} placeholder="https://..."/></label></>}
          {!['source','filter','gate','agent','dataset','deliver'].includes(selectedFlowNode.type)&&<label className="inspector-wide">节点配置<input value={String(selectedFlowNode.config['schema']??selectedFlowNode.config['strategy']??selectedFlowNode.config['model']??selectedFlowNode.config['format']??'default')} onChange={event=>updateNode(selectedFlowNode.type==='normalize'?'schema':selectedFlowNode.type==='dedupe'?'strategy':selectedFlowNode.type==='llm'?'model':selectedFlowNode.type==='report'?'format':'mode',event.target.value)}/></label>}
          {selectedFlowNode.type!=='source'&&<fieldset className="upstream-picker"><legend>上游节点（支持分支与汇聚）</legend>{spec.nodes.filter(node=>node.id!==selectedFlowNode.id).map(node=>{const checked=spec.edges.some(edge=>edge.source===node.id&&edge.target===selectedFlowNode.id),cycle=reaches(spec,selectedFlowNode.id,node.id);return <label key={node.id}><input type="checkbox" checked={checked} disabled={!checked&&cycle} onChange={event=>toggleUpstream(node.id,event.target.checked)}/>{node.label}<small>{node.type}</small></label>})}</fieldset>}
          <p>连线决定真实执行依赖；可用“上游节点”构建并行分支与多路汇聚。发布时服务端会验证断链、循环、配置和执行能力。</p></aside>}
      </>:<div className="studio-empty large">先在“项目”中创建并打开一个工作流。</div>}</section>
    </div>}

    {tab==='runs'&&<div className="product-page"><div className="section-title page-title"><div><h3>运行记录与节点 Trace</h3><p>每个发布版本都保留事件、检查点、状态和最终输出</p></div><span>{data.runs.length} runs</span></div><div className="run-board">{data.runs.map(run=>{const points=data.checkpoints.filter(point=>point.run_id===run.id);const events=data.events.filter(item=>item.run_id===run.id);return <article className="run-card" key={run.id}><header><span className={`status ${run.status}`}><i/>{run.status}</span><div><strong>{run.workflow_name} · v{run.version}</strong><small>{run.project_name??'未归档项目'} · {date(run.started_at)}</small></div><code>{run.job_id.slice(0,8)}</code></header><div className="checkpoint-track">{points.map((point,index)=><div key={point.id} className={point.status}><i>{index+1}</i><span><strong>{point.node_id}</strong><small>{point.status} · {date(point.finished_at??point.started_at)}</small></span></div>)}</div><details><summary>查看事件时间线（{events.length}）</summary>{events.map(item=><p key={item.id}><code>{item.node_id}</code><span>{item.message}</span><time>{date(item.created_at)}</time></p>)}</details></article>;})}{!data.runs.length&&<div className="studio-empty large">发布并运行工作流后，这里会显示节点 Trace。</div>}</div></div>}

    {tab==='evidence'&&<div className="product-page"><div className="section-title page-title"><div><h3>证据关系工作台</h3><p>从 AI 发现回溯到原始记录，并沉淀跨记录关系</p></div><span>{data.evidenceLinks.length} links</span></div><div className="evidence-board"><section className="finding-column">{data.evidence.map(item=><article key={item.id}><header><b>S{item.severity}</b><div><strong>{item.theme}</strong><small>{item.source_count} 条来源 · {item.linked_count} 条已关联</small></div></header><p>{item.summary}</p><div className="linked-records">{data.evidenceLinks.filter(link=>link.evidence_id===item.id).slice(0,8).map(link=><a key={link.id} href={link.url??'#'} target={link.url?'_blank':undefined} rel="noreferrer"><i>{link.platform.slice(0,1).toUpperCase()}</i><span><strong>{link.title??'原始记录'}</strong><small>{link.author??link.platform}</small></span></a>)}</div></article>)}</section><aside className="relationship-column"><h3>关系投影</h3><p>同一证据簇中的记录自动形成可查询关系。</p>{data.relationships.map(item=><article key={item.id}><span>{item.source_title??'记录 A'}</span><b>{item.relation}<small>{item.confidence}%</small></b><span>{item.target_title??'记录 B'}</span></article>)}{!data.relationships.length&&<div className="studio-empty">完成新的分析任务后自动生成。</div>}</aside></div></div>}

    {tab==='resources'&&<div className="product-page"><div className="resource-layout"><section><div className="section-title"><div><h3>Worker Fleet</h3><p>出站轮询、能力路由、浏览器配置与健康心跳</p></div><span>{data.nodes.filter(node=>node.status==='online').length} 在线</span></div><div className="fleet-grid">{data.nodes.map(node=>{const runtime=safeJson<Record<string,unknown>>(node.runtime_json,{}),health=safeJson<Record<string,unknown>>(node.health_json,{}),caps=safeJson<string[]>(node.capabilities_json,[]),attestation=runtime['browserAttestation']&&typeof runtime['browserAttestation']==='object'?runtime['browserAttestation'] as Record<string,unknown>:null,browserReady=attestation?.['verified']===true&&typeof attestation['expiresAt']==='string';return <article key={node.id}><header><span className="worker-mark">⌘</span><div><strong>{node.name}</strong><small>{node.platform} · v{node.version}</small></div><b className={node.status}>{node.status}</b></header><dl><div><dt>并发槽位</dt><dd>{node.active_jobs} / {node.max_concurrency}</dd></div><div><dt>传输</dt><dd>{String(runtime['transport']??'worker')}</dd></div><div><dt>浏览器自动化</dt><dd>{browserReady?`${String(attestation?.['profileKind'])} 已证明`:'未通过 Profile 证明'}</dd></div><div><dt>健康</dt><dd>{String(health['state']??'unknown')}</dd></div></dl><div className="cap-tags">{caps.slice(0,8).map(cap=><code key={cap}>{cap}</code>)}{caps.length>8&&<code>+{caps.length-8}</code>}</div></article>})}</div></section><aside className="profile-panel"><div className="section-title"><div><h3>浏览器 Profile</h3><p>Profile 类型必须与 Worker 的实时 CDP 证明一致。</p></div></div><form className="compact-form" onSubmit={createProfile}><input name="name" required placeholder="配置显示名称"/><input name="profileName" required placeholder="Worker 中的 Profile 名"/><select name="profileKind"><option value="authenticated">登录态 Profile</option><option value="anonymous">匿名干净 Profile</option></select><select name="mode"><option value="cdp">CDP</option><option value="bridge">Bridge</option><option value="local">Local</option></select><select name="nodeId" defaultValue=""><option value="">自动路由节点</option>{data.nodes.map(node=><option value={node.id} key={node.id}>{node.name}</option>)}</select><input name="sites" placeholder="站点绑定，逗号分隔"/><input name="noVncUrl" type="url" placeholder="noVNC HTTPS 地址（可选）"/><input name="cdpUrl" placeholder="CDP WSS 地址（可选，不展示密钥）"/><button disabled={busy||!canWrite}>保存 Profile</button></form><div className="profile-list">{data.profiles.map(item=>{const noVnc=safeProfileUrl(item.no_vnc_url??item.noVncUrl),hasCdp=Boolean(item.cdp_url??item.cdpUrl);return <article key={item.id}><i>◉</i><div><strong>{item.name}</strong><small>{item.profile_name} · {item.mode} · {item.profile_kind??'authenticated'}</small><code>{safeJson<string[]>(item.site_bindings_json,[]).join(' · ')||'任意站点'}</code><small>CDP {hasCdp?'已配置':'未配置'} · 证明 {item.last_verified_at?'有效记录':'尚未验证'} · noVNC {noVnc?'可用':'未配置'}</small></div><span className="profile-actions"><b>{item.status}</b>{noVnc&&<a href={noVnc} target="_blank" rel="noreferrer">安全打开 ↗</a>}</span></article>})}</div></aside></div><BrowserAutomationPanel profiles={data.profiles} nodes={data.nodes} canWrite={canWrite}/></div>}

    {tab==='plugins'&&<div className="product-page integrations-page"><div className="section-title page-title"><div><h3>能力与插件中心</h3><p>已接入能力可直接配置、调用和追踪，不再停留在能力占位</p></div><span>{data.plugins.filter(item=>item.status==='installed').length} ready</span></div>
      <div className="plugin-grid">{data.plugins.map(item=>{const caps=safeJson<string[]>(item.capabilities_json,[]),implemented=item.status==='installed';return <article key={item.id} className={item.status}><header><span>{item.kind==='source'?'◎':item.kind==='runtime'?'⌘':item.kind==='delivery'?'↗':'◆'}</span><b>{implemented?'已接入':'未启用'}</b></header><h3>{item.name}</h3><p>{item.plugin_key} · v{item.version}</p><div>{caps.map(cap=><code key={cap}>{cap}</code>)}</div></article>})}</div>
      <div className="integration-grid">
        <section className="integration-card"><header><span>DI</span><div><h3>Dify DSL 导入</h3><p>把 Dify YAML 转换为可编辑、可发布的 ThreadBeacon 工作流。</p></div></header><form onSubmit={importDify}><label>目标项目<select name="projectId" required value={selectedProject} onChange={event=>setSelectedProject(event.target.value)}>{data.projects.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>绑定项目数据源<select name="projectSourceId" required defaultValue=""><option value="" disabled>{projectSources.length?'选择可运行来源':'请先在项目页登记来源'}</option>{projectSources.map(source=><option key={source.id} value={source.id}>{source.name} · {source.kind}</option>)}</select></label><label className="file-drop">YAML / YML 文件<input name="file" type="file" accept=".yaml,.yml,application/yaml,text/yaml" required/><small>仅导入节点、连接与安全配置；密钥值不会落库。</small></label><button disabled={busy||!data.projects.length||!projectSources.length}>导入并打开画布</button></form>{!projectSources.length&&<p className="integration-warning">当前项目没有数据源。请先回到“项目”登记并试运行来源，避免生成不可执行的默认 Web 节点。</p>}</section>
        <section className="integration-card"><header><span>WH</span><div><h3>Webhook 触发器</h3><p>外部系统通过一次性令牌触发已发布工作流。</p></div></header><form onSubmit={createWebhook}><label>项目<select name="projectId" required value={selectedProject} onChange={event=>setSelectedProject(event.target.value)}>{data.projects.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>触发器名称<input name="name" required placeholder="例如：产品反馈入站"/></label><label>已发布工作流<select name="workflowId" required defaultValue=""><option value="" disabled>选择工作流</option>{projectWorkflows.map(item=><option key={item.id} value={item.id}>{item.name} · v{item.published_version}</option>)}</select></label><button disabled={busy||!projectWorkflows.length}>创建触发器</button></form>{webhookToken&&<div className="secret-reveal" role="status"><strong>触发地址仅在本次显示</strong><code>{webhookToken}</code><button type="button" onClick={()=>void copyText('webhook',webhookToken)}>{copied==='webhook'?'已复制':'复制地址'}</button></div>}<div className="webhook-list">{webhooks.map(item=><article key={item.id}><div><strong>{item.name}</strong><small>{item.last_triggered_at?`最近触发 ${date(item.last_triggered_at)}`:'尚未触发'}</small></div><button type="button" disabled={busy} onClick={()=>void toggleWebhook(item)}>{item.enabled?'停用':'启用'}</button></article>)}{!webhooks.length&&<p className="integration-empty">尚未创建触发器。</p>}</div></section>
        <section className="integration-card mcp-card"><header><span>MC</span><div><h3>MCP Server</h3><p>让支持 MCP 的 Agent 查询能力、创建任务并读取执行结果。</p></div></header><dl><div><dt>HTTP Endpoint</dt><dd><code>{typeof location==='undefined'?'/api/mcp':`${location.origin}/api/mcp`}</code><button type="button" onClick={()=>void copyText('mcp',`${location.origin}/api/mcp`)}>{copied==='mcp'?'已复制':'复制'}</button></dd></div><div><dt>认证</dt><dd><code>Authorization: Bearer threadbeacon_…</code></dd></div><div><dt>传输</dt><dd>Streamable HTTP · JSON-RPC 2.0</dd></div></dl><pre>{`{\n  "mcpServers": {\n    "threadbeacon": {\n      "url": "${typeof location==='undefined'?'https://YOUR_HOST/api/mcp':`${location.origin}/api/mcp`}",\n      "headers": { "Authorization": "Bearer YOUR_TOKEN" }\n    }\n  }\n}`}</pre><a href="/api/mcp" target="_blank" rel="noreferrer">检查 MCP 服务信息 ↗</a><div className="token-manager"><div><h4>Personal API Tokens</h4><p>明文仅创建时显示，不会保存在浏览器中。</p></div><form onSubmit={createToken}><input name="name" required placeholder="Token 名称" aria-label="Token 名称"/><select name="expiresInDays" defaultValue="30" aria-label="有效期"><option value="7">7 天</option><option value="30">30 天</option><option value="90">90 天</option><option value="365">1 年</option></select><button disabled={busy}>创建 Token</button></form>{plainToken&&<div className="secret-reveal token-secret" role="status"><strong>请立即复制，关闭页面后无法再次查看</strong><code>{plainToken}</code><button type="button" onClick={()=>void copyText('token',plainToken)}>{copied==='token'?'已复制':'复制 Token'}</button></div>}<div className="token-list">{apiTokens.map(token=><article key={token.id}><div><strong>{token.name}</strong><small>{token.token_prefix??'threadbeacon_…'} · {token.expires_at?`到期 ${date(token.expires_at)}`:'未提供到期时间'}{token.last_used_at?` · 最近使用 ${date(token.last_used_at)}`:''}</small></div><b className={token.revoked_at?'revoked':'active'}>{token.revoked_at?'已撤销':'有效'}</b>{!token.revoked_at&&<button type="button" disabled={busy} onClick={()=>void revokeToken(token.id)}>撤销</button>}</article>)}{!apiTokens.length&&<p className="integration-empty">尚未创建 API Token。</p>}</div></div></section>
      </div><div className="capability-note"><strong>运行时能力发现</strong><p>平台目录由在线 Worker 的 capabilities_json 动态聚合；任意符合 opencli:&lt;site&gt; 的只读适配器都可以进入来源节点，无需等待前端发版。</p></div>
    </div>}

    {tab==='access'&&<div className="product-page access-page"><div className="section-title page-title"><div><h3>团队与权限</h3><p>工作区成员采用最小权限角色；后端会对每次写操作再次鉴权。</p></div><span>{currentRole}</span></div><div className="access-layout"><section className="panel"><div className="panel-head"><div><h3>成员</h3><p>{accessMembers.length} 位成员 · 你的角色是 {currentRole}</p></div></div><div className="member-list">{accessMembers.map(member=><article key={member.id}><span>{(member.display_name??member.email).slice(0,1).toUpperCase()}</span><div><strong>{member.display_name??member.email}</strong><small>{member.email} · {member.status??'active'}</small></div><select aria-label={`修改 ${member.email} 的角色`} value={member.role} disabled={!canManageAccess||busy||member.role==='owner'} onChange={event=>void updateMember(member.id,event.target.value)}><option value="editor">Editor</option><option value="viewer">Viewer</option>{member.role==='owner'&&<option value="owner">Owner</option>}</select>{member.role!=='owner'&&<button type="button" disabled={!canManageAccess||busy} onClick={()=>void updateMember(member.id,member.role,'remove')}>移除</button>}</article>)}{!accessMembers.length&&<div className="studio-empty">成员列表尚未加载或当前只有你一人。</div>}</div></section><aside className="access-invite"><div className="section-title"><div><h3>邀请成员</h3><p>邀请后可随时调整角色或移除。</p></div></div><form className="compact-form" onSubmit={inviteMember}><label>成员邮箱<input name="email" type="email" required placeholder="name@example.com"/></label><label>角色<select name="role" defaultValue="viewer"><option value="viewer">Viewer · 只读</option><option value="editor">Editor · 可编辑与运行</option></select></label><button disabled={!canManageAccess||busy}>发送邀请</button></form>{inviteUrl&&<div className="secret-reveal" role="status"><strong>邀请链接仅在本次显示</strong><code>{inviteUrl}</code><button type="button" onClick={()=>void copyText('invite',inviteUrl)}>{copied==='invite'?'已复制':'复制邀请链接'}</button></div>}<div className="role-guide"><article><b>Owner</b><p>管理成员、配置、运行与治理。</p></article><article><b>Editor</b><p>创建项目、工作流、任务和交付规则。</p></article><article><b>Viewer</b><p>只读查看项目、运行、证据与审计。</p></article></div>{!canManageAccess&&<p className="permission-hint">当前角色无权管理成员。如需变更，请联系 workspace owner。</p>}</aside></div></div>}

    {tab==='delivery'&&<div className="product-page"><div className="governance-layout"><section className="panel"><div className="panel-head"><div><h3>交付规则</h3><p>凭据加密保存，完成任务后自动投递</p></div></div><form className="delivery-form" onSubmit={createRule}><input name="name" required placeholder="规则名称"/><select name="kind"><option value="webhook">Webhook</option><option value="feishu">飞书</option><option value="dingtalk">钉钉</option><option value="wecom">企业微信</option><option value="email">Email HTTPS Gateway</option></select><input name="endpoint" type="url" required placeholder="https://..."/><button disabled={busy}>添加交付</button></form><div className="rule-list">{data.rules.map(rule=><button key={rule.id} onClick={()=>void toggleRule(rule.id)}><span><strong>{rule.name}</strong><small>{rule.kind}</small></span><b>{rule.enabled?'已启用':'已暂停'}</b></button>)}</div></section><section className="panel"><div className="panel-head"><div><h3>审计日志</h3><p>项目、工作流、任务和资源变更</p></div></div><div className="audit-list">{data.auditLogs.map(item=><article key={item.id}><code>{item.action}</code><span>{item.resource_type}<small>{date(item.created_at)}</small></span></article>)}</div></section></div></div>}
    </section>
  </main>;
}
